"""Browser-native EconAtlas chat workspace (no WebSocket dependency)."""

WORKSPACE_HTML = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EconAtlas KMS</title><style>
*{box-sizing:border-box}body{margin:0;font-family:Inter,"PingFang SC","Microsoft YaHei",sans-serif;color:#172033;background:#f7f9fc}button,textarea,input{font:inherit}.top{height:70px;background:#fff;border-bottom:1px solid #e8ecf3;display:flex;align-items:center;padding:0 26px;gap:42px;position:fixed;inset:0 0 auto;z-index:5}.brand{display:flex;align-items:center;gap:11px;font-size:20px;font-weight:750;color:#234272}.mark{width:34px;height:34px;border-radius:11px;background:linear-gradient(135deg,#4d7cff,#7659ff);display:grid;place-items:center;color:#fff}.nav{display:flex;gap:28px;height:100%;align-items:center}.nav span{height:100%;display:flex;align-items:center;color:#526079;font-weight:600}.nav .active{color:#4f6fff;border-bottom:3px solid #4f6fff}.search{margin-left:auto;border:1px solid #dde3ee;border-radius:8px;padding:10px 16px;color:#a7b0c1;width:260px}.new{border:1px solid #6d62ff;background:#fff;color:#6658f5;border-radius:7px;padding:9px 18px}.side{position:fixed;left:0;top:70px;bottom:0;width:290px;background:#fff;border-right:1px solid #e4e8f0;padding:18px}.side-title{background:#eef2ff;color:#4f6fff;padding:15px;border-radius:7px;font-weight:700}.side input{width:100%;margin-top:16px;border:1px solid #dce3ef;border-radius:6px;padding:11px}.muted{color:#97a2b5;font-size:13px;margin:28px 10px 12px}.history{padding:12px 10px;border-radius:7px;color:#4c5a71;line-height:1.5}.online{position:absolute;bottom:22px;left:28px;color:#5d6b82;font-size:13px}.dot{display:inline-block;width:8px;height:8px;background:#27c58b;border-radius:50%;margin-right:7px}.main{margin-left:290px;padding-top:70px;min-height:100vh}.stage{max-width:920px;margin:auto;padding:90px 30px 150px}.hero{text-align:center;margin:52px 0 34px}.hero .icon{width:54px;height:54px;margin:auto;border-radius:18px;background:linear-gradient(135deg,#506fff,#8b65ff);display:grid;place-items:center;color:#fff;font-size:25px}.hero h1{font-size:30px;margin:20px 0 8px}.hero p{color:#8490a4}.chips{display:flex;justify-content:center;gap:10px;flex-wrap:wrap}.chips button{border:1px solid #e0e6f0;background:#fff;border-radius:18px;padding:8px 14px;color:#657189;cursor:pointer}.messages{margin:34px 0}.msg{display:flex;gap:12px;margin:18px 0}.bubble{max-width:78%;padding:14px 17px;border-radius:13px;line-height:1.7;white-space:pre-wrap}.user{justify-content:flex-end}.user .bubble{background:#5d6ff2;color:#fff}.bot .bubble{background:#fff;border:1px solid #e4e8f0;box-shadow:0 5px 20px #243a6510}.evidence{margin-top:10px;font-size:12px;color:#77839a}.composer{position:fixed;left:calc(290px + (100vw - 290px - 860px)/2);bottom:28px;width:min(860px,calc(100vw - 340px));background:#fff;border:1px solid #dfe5ef;border-radius:16px;padding:14px;box-shadow:0 12px 36px #1d31551c}.composer textarea{width:100%;border:0;outline:0;resize:none;height:52px;color:#26324a}.tools{display:flex;align-items:center}.model{font-size:12px;color:#655af2;background:#f2f0ff;padding:7px 10px;border-radius:8px}.send{margin-left:auto;border:0;border-radius:9px;background:#5b6ff1;color:#fff;padding:9px 18px;cursor:pointer}.send:disabled{opacity:.5}.status{font-size:12px;color:#8b96a8;margin-left:10px}@media(max-width:800px){.nav,.search{display:none}.side{display:none}.main{margin-left:0}.composer{left:20px;width:calc(100vw - 40px)}.top{gap:15px}.stage{padding-top:55px}}
</style></head><body><header class="top"><div class="brand"><div class="mark">◈</div><div>EconAtlas KMS</div></div><nav class="nav"><span>首页</span><span>数据资产</span><span>指标百科</span><span>知识图谱</span><span class="active">智能问答</span></nav><div class="search">搜索指标、国家或功能　⌕</div><button class="new" onclick="resetChat()">＋ 新建</button></header><aside class="side"><div class="side-title">▣　对话 <b style="float:right">＋</b></div><input placeholder="搜索会话标题"><div class="muted">最近 30 天</div><div class="history">询问当前模型</div><div class="online"><span class="dot"></span>知识库已连接 · DeepSeek</div></aside><main class="main"><section class="stage"><div class="hero" id="hero"><div class="icon">✦</div><h1>基于宏观数据知识库的 AI 问答</h1><p>自动识别国家、指标与时间范围，基于可追溯官方数据生成回答</p><div class="chips"><button onclick="ask(this.textContent)">中国近五年的通胀趋势</button><button onclick="ask(this.textContent)">美国失业率最新水平</button><button onclick="ask(this.textContent)">德国 GDP 增速如何变化</button></div></div><div class="messages" id="messages"></div></section></main><div class="composer"><textarea id="question" placeholder="直接向 EconAtlas 提问；Enter 发送，Shift+Enter 换行"></textarea><div class="tools"><span class="model">智能推理 · DeepSeek</span><span class="status" id="status"></span><button class="send" id="send" onclick="submitQuestion()">发送 ➤</button></div></div><script>
let context=null;const q=document.getElementById('question'),messages=document.getElementById('messages'),statusEl=document.getElementById('status'),send=document.getElementById('send');q.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();submitQuestion()}});function markdown(text){return text.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\[E(\d+)\]/g,'<span class="model">[E$1]</span>').replace(/\n/g,'<br>')}function add(role,text,evidence=[]){document.getElementById('hero').style.display='none';const el=document.createElement('div');el.className='msg '+role;const b=document.createElement('div');b.className='bubble';b.innerHTML=markdown(text);if(evidence.length){const x=document.createElement('div');x.className='evidence';x.textContent='数据证据：'+evidence.length+' 条 · 来源：'+[...new Set(evidence.map(v=>v.source_organization).filter(Boolean))].join('、');b.appendChild(x)}el.appendChild(b);messages.appendChild(el);window.scrollTo({top:document.body.scrollHeight,behavior:'smooth'})}function ask(t){q.value=t;submitQuestion()}async function submitQuestion(){const text=q.value.trim();if(!text||send.disabled)return;add('user',text);q.value='';send.disabled=true;statusEl.textContent='正在理解问题…';try{const r=await fetch('/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:text,context})});const d=await r.json();if(!r.ok||d.error)throw new Error(d.error||'请求失败');context=d.context;add('bot',d.answer,d.evidence||[])}catch(e){add('bot','暂时无法生成回答：'+e.message)}finally{send.disabled=false;statusEl.textContent=''}}function resetChat(){messages.innerHTML='';context=null;document.getElementById('hero').style.display='block';q.focus()}
</script></body></html>'''
